/** void BlendPalettesGradually(u32 selectedPalettes, s8 delay, u8 coeff, u8 coeffTarget, u16 color, u8 priority, u8 id) */
export function BlendPalettesGradually(selectedPalettes: any, delay: any, coeff: any, coeffTarget: any, color: any, priority: any, id: any): any {
  let taskId: any = null;

      taskId = CreateTask(Task_BlendPalettesGradually, priority);
      gTasks[taskId].tCoeff = coeff;
      gTasks[taskId].tCoeffTarget = coeffTarget;

      if (delay >= 0)
      {
          gTasks[taskId].tDelay = delay;
          gTasks[taskId].tCoeffDelta = 1;
      }
      else
      {
          gTasks[taskId].tDelay = 0;
          gTasks[taskId].tCoeffDelta = -delay + 1;
      }

      if (coeffTarget < coeff)
          gTasks[taskId].tCoeffDelta *= -1;

      SetWordTaskArg(taskId, tPalettes, selectedPalettes);
      gTasks[taskId].tColor = color;
      gTasks[taskId].tId = id;
      gTasks[taskId].func(taskId);
}

/** static void Task_BlendPalettesGradually(u8 taskId) */
export function Task_BlendPalettesGradually(taskId: any): any {
  let palettes: any = null;
      let data: any = null;
      let target: any = null;

      data = gTasks[taskId].data;
      palettes = GetWordTaskArg(taskId, tPalettes);

      if (++tDelayTimer > tDelay)
      {
          tDelayTimer = 0;
          BlendPalettes(palettes, tCoeff, tColor);
          target = tCoeffTarget;
          if (tCoeff == target)
          {
              DestroyTask(taskId);
          }
          else
          {
              tCoeff += tCoeffDelta;
              if (tCoeffDelta >= 0)
              {
                  if (tCoeff < target)
                      return;
              }
              else if (tCoeff > target)
              {
                  return;
              }
              tCoeff = target;
          }
      }
}

